// VerifyBlockDepositLength (beacon-chain/core/electra/transition.go:134-160)
func VerifyBlockDepositLength(body interfaces.ReadOnlyBeaconBlockBody, state state.BeaconState) error {
    eth1Data := state.Eth1Data()
    requestsStartIndex, err := state.DepositRequestsStartIndex()
    if err != nil {
        return errors.Wrap(err, "failed to get requests start index")
    }
    eth1DepositIndexLimit := min(eth1Data.DepositCount, requestsStartIndex)
    if state.Eth1DepositIndex() < eth1DepositIndexLimit {
        if uint64(len(body.Deposits())) != min(params.BeaconConfig().MaxDeposits, eth1DepositIndexLimit-state.Eth1DepositIndex()) {
            return fmt.Errorf("incorrect outstanding deposits in block body, wanted: %d, got: %d", ...)
        }
    } else {
        if len(body.Deposits()) != 0 {
            return fmt.Errorf("incorrect outstanding deposits in block body, wanted: %d, got: %d", 0, len(body.Deposits()))
        }
    }
    return nil
}
// Note: VerifyBlockDepositLength checks deposit COUNT only, not contract address.
// parse_deposit_requests address filtering is performed in go-ethereum (EL) before requests reach Prysm.
// Prysm receives pre-filtered DepositRequest protos via engine API and trusts EL filtering per EIP-6110.

// DepositRequestFromConsensus (conversions_block_execution.go ~line 887)
// Pure conversion, no validation:
func DepositRequestFromConsensus(d *enginev1.DepositRequest) *DepositRequest {
    return &DepositRequest{
        Pubkey:                hexutil.Encode(d.Pubkey),
        WithdrawalCredentials: hexutil.Encode(d.WithdrawalCredentials),
        Amount:                fmt.Sprintf("%d", d.Amount),
        Signature:             hexutil.Encode(d.Signature),
        Index:                 fmt.Sprintf("%d", d.Index),
    }
}

// ToConsensus (conversions_block_execution.go ~line 897)
// Validates fields in order: pubkey -> withdrawalCredentials -> amount -> signature -> index
func (d *DepositRequest) ToConsensus() (*enginev1.DepositRequest, error) {
    if d == nil { return nil, server.NewDecodeError(errNilValue, "DepositRequest") }
    pubkey, err := bytesutil.DecodeHexWithLength(d.Pubkey, fieldparams.BLSPubkeyLength)  // exact 48-byte check
    if err != nil { return nil, server.NewDecodeError(err, "Pubkey") }
    withdrawalCredentials, err := bytesutil.DecodeHexWithLength(d.WithdrawalCredentials, fieldparams.RootLength)  // exact 32-byte check
    if err != nil { return nil, server.NewDecodeError(err, "WithdrawalCredentials") }
    amount, err := strconv.ParseUint(d.Amount, 10, 64)  // uint64 range enforced
    if err != nil { return nil, server.NewDecodeError(err, "Amount") }
    sig, err := bytesutil.DecodeHexWithLength(d.Signature, fieldparams.BLSSignatureLength)  // exact 96-byte check
    if err != nil { return nil, server.NewDecodeError(err, "Signature") }
    index, err := strconv.ParseUint(d.Index, 10, 64)  // uint64 range enforced (cannot overflow)
    if err != nil { return nil, server.NewDecodeError(err, "Index") }
    return &enginev1.DepositRequest{Pubkey: pubkey, WithdrawalCredentials: withdrawalCredentials, Amount: amount, Signature: sig, Index: index}, nil
}
